(() => {
  const toast = document.querySelector('#adminToast');
  const showToast = (message) => { toast.textContent = message; toast.classList.add('show'); window.setTimeout(() => toast.classList.remove('show'), 2200); };
  document.querySelector('#exportTopBtn')?.remove();
  const time = document.querySelector('#currentTime'); if (time) time.textContent = new Date().toLocaleString('zh-CN', { hour12: false }).replace(/\//g, '-');
  document.querySelectorAll('.admin-nav button').forEach((button) => button.addEventListener('click', () => { document.querySelectorAll('.admin-nav button').forEach((item) => item.classList.remove('active')); button.classList.add('active'); document.querySelectorAll('.admin-section').forEach((section) => section.classList.toggle('active', section.id === button.dataset.section)); }));
  const body = document.querySelector('#recordBody');
  const table = body?.closest('table');
  if (table) { const head = table.tHead.rows[0]; const checkHead = document.createElement('th'); checkHead.innerHTML = '<input type="checkbox" id="selectAllRecords" aria-label="全选记录">'; head.insertBefore(checkHead, head.firstChild); [...body.rows].forEach((row) => { const cell = row.insertCell(0); cell.innerHTML = '<input type="checkbox" class="record-check" aria-label="选择此记录">'; }); }
  const filter = () => { const query = (document.querySelector('#searchInput')?.value || '').trim().toLowerCase(); const status = document.querySelector('#statusFilter')?.value || ''; [...body.rows].forEach((row) => { row.hidden = (query && !row.textContent.toLowerCase().includes(query)) || (status && row.dataset.status !== status); }); };
  document.querySelector('#searchInput')?.addEventListener('input', filter); document.querySelector('#statusFilter')?.addEventListener('change', filter); document.querySelector('#clearFilterBtn')?.addEventListener('click', () => { document.querySelector('#searchInput').value = ''; document.querySelector('#statusFilter').value = ''; filter(); });
  document.querySelector('#selectAllRecords')?.addEventListener('change', (event) => { [...body.querySelectorAll('.record-check')].filter((box) => !box.closest('tr').hidden).forEach((box) => { box.checked = event.target.checked; }); });
  const exportData = (selectedOnly) => { const records = [...body.querySelectorAll('tr')].filter((row) => !row.hidden && (!selectedOnly || row.querySelector('.record-check')?.checked)); if (selectedOnly && !records.length) { showToast('请先勾选要导出的记录'); return; } const rows = records.map((row) => [...row.cells].slice(1, 12).map((cell) => `"${cell.textContent.trim().replace(/"/g, '""')}"`).join(',')); const csv = ['问卷编号,提交时间,地区,汽车品牌,风险事件,状态,预留字段1,预留字段2,预留字段3,预留字段4,预留字段5', ...rows].join('\n'); const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = selectedOnly ? 'selected-survey-records.csv' : 'all-survey-records.csv'; link.click(); URL.revokeObjectURL(link.href); showToast(selectedOnly ? `已导出 ${records.length} 条选中记录` : '全部数据已导出'); };
  const exportBtn = document.querySelector('#exportBtn'); if (exportBtn) { exportBtn.textContent = '导出全部数据'; exportBtn.insertAdjacentHTML('afterend', '<button class="btn btn-secondary" id="exportSelectedBtn">导出选中的记录</button>'); }
  document.querySelector('#exportBtn')?.addEventListener('click', () => exportData(false)); document.querySelector('#exportSelectedBtn')?.addEventListener('click', () => exportData(true));
  document.querySelector('#addRecordBtn')?.addEventListener('click', () => showToast('新增记录表单已预留，可接入后端接口'));
  body.addEventListener('click', (event) => { const row = event.target.closest('tr'); if (!row) return; if (event.target.closest('.delete-record')) { row.remove(); showToast('记录已删除'); } if (event.target.closest('.edit-record')) showToast('已打开记录编辑状态'); });
  const recordsTitleNote=document.querySelector('#records .admin-title > div > p');if(recordsTitleNote)recordsTitleNote.remove();const selectedButton=document.querySelector('#exportSelectedBtn');if(selectedButton)selectedButton.textContent='导出选中的数据';const recordsTools=document.querySelector('#records .admin-title .admin-tools');const exportAllButton=document.querySelector('#exportBtn');const addRecordButton=document.querySelector('#addRecordBtn');const recordsFilters=document.querySelector('#records .filters');if(addRecordButton)addRecordButton.remove();if(recordsTools&&exportAllButton&&exportAllButton.parentNode!==recordsTools)recordsTools.appendChild(exportAllButton);if(recordsTools&&recordsTools.parentNode!==document.querySelector('#records .admin-title'))document.querySelector('#records .admin-title').appendChild(recordsTools);if(selectedButton&&recordsFilters){recordsFilters.appendChild(selectedButton);}const count=document.querySelector('#recordCount');if(count)count.textContent='每页 30 条 · 当前展示示例记录，共 102,486 条';
  const team=document.querySelector('#team .team-grid');if(team){team.className='card panel team-source';team.innerHTML='<p>欢迎更多伙伴加入，咨询方式：<a href="mailto:Luojia.robot@hotmail.com">Luojia.robot@hotmail.com</a>。</p><h2>团队职责</h2><div class="team-duty-grid"><article><h3>研究与课题组</h3><p>负责研究问题设计、指标体系、样本策略和调研报告分析，聚焦 AI 赋能智驾汽车的关键任务、挑战与路径。</p></article><article><h3>数据与方法组</h3><p>负责数据质量、问卷逻辑、字段治理、统计分析和隐私保护，确保记录可复核、可追踪、可扩展。</p></article><article><h3>产品与体验组</h3><p>负责问卷调查的维护更新，包括功能、可访问性、移动端适配和反馈闭环，持续改善填写与管理体验。</p></article></div><h2>团队成员</h2><div class="table-scroll"><table class="data-table team-table"><thead><tr><th>成员</th><th>研究方向</th><th>联系方式</th><th>职责</th></tr></thead><tbody><tr><td>岚</td><td>产业经济</td><td>—</td><td>项目秘书长，统筹对外协调和管理、业务合作</td></tr><tr><td>王教授</td><td>技术创新、智能经济</td><td>—</td><td>行业建模与分析、数据分析</td></tr><tr><td>若谷</td><td>智驾大模型</td><td>ruogu-autodriving</td><td>数学建模、AI Infra、智驾场景需求分析</td></tr><tr><td>森林</td><td>AI Coding</td><td>—</td><td>数据挖掘、数据管理</td></tr><tr><td>石溪</td><td>技术经济</td><td>—</td><td>问卷推广、行业媒体沟通</td></tr><tr><td>文书</td><td>—</td><td><a href="mailto:Luojia.robot@hotmail.com">Luojia.robot@hotmail.com</a></td><td>文档归档、内部知识库建设</td></tr><tr><td>等你到来</td><td>等你到来</td><td>等你到来</td><td>等你到来</td></tr></tbody></table></div>'}
})();
